{
  "items": [
    {
      "name": "Polynomial.taylor",
      "type": " {R : Type u_1} [Semiring R] (r : R) : Polynomial R →ₗ[R] Polynomial R",
      "module": "Mathlib.Algebra.Polynomial.Taylor"
    },
    {
      "name": "Polynomial.taylor_zero'",
      "type": " {R : Type u_1} [Semiring R] : Polynomial.taylor 0 = LinearMap.id",
      "module": "Mathlib.Algebra.Polynomial.Taylor"
    },
    {
      "name": "Polynomial.leadingCoeff_taylor",
      "type": " {R : Type u_1} [Semiring R] (r : R) (f : Polynomial R) : ((Polynomial.taylor r) f).leadingCoeff = f.leadingCoeff",
      "module": "Mathlib.Algebra.Polynomial.Taylor"
    },
    {
      "name": "Polynomial.natDegree_taylor",
      "type": " {R : Type u_1} [Semiring R] (p : Polynomial R) (r : R) : ((Polynomial.taylor r) p).natDegree = p.natDegree",
      "module": "Mathlib.Algebra.Polynomial.Taylor"
    },
    {
      "name": "Polynomial.degree_taylor",
      "type": " {R : Type u_1} [Semiring R] (p : Polynomial R) (r : R) : ((Polynomial.taylor r) p).degree = p.degree",
      "module": "Mathlib.Algebra.Polynomial.Taylor"
    },
    {
      "name": "Polynomial.taylor_zero",
      "type": " {R : Type u_1} [Semiring R] (f : Polynomial R) : (Polynomial.taylor 0) f = f",
      "module": "Mathlib.Algebra.Polynomial.Taylor"
    },
    {
      "name": "Polynomial.coeff_taylor_natDegree",
      "type": " {R : Type u_1} [Semiring R] (r : R) (f : Polynomial R) : ((Polynomial.taylor r) f).coeff f.natDegree = f.leadingCoeff",
      "module": "Mathlib.Algebra.Polynomial.Taylor"
    },
    {
      "name": "Polynomial.taylor_eq_zero",
      "type": " {R : Type u_1} [Semiring R] (r : R) (f : Polynomial R) : (Polynomial.taylor r) f = 0 ↔ f = 0",
      "module": "Mathlib.Algebra.Polynomial.Taylor"
    }
  ]
}
